-- 6.7M sensor readings from USGS water monitoring stations -- streamflow, groundwater, and water quality by site and time.
-- Auto-generated by scripts/gen_evidence_pages.py: 6,694,816 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("DATETIME") as year, count(*) as records
from THE_LIBRARY.ENERGY_ENVIRONMENT.WATER_MONITORING_READINGS
where "DATETIME" is not null
group by 1
order by 1
